/// <reference lib="webworker" />

type ImageRequest = {
  type: "image";
  id: string;
  src: string;
  size: number;
};

type GradientRequest = {
  type: "gradient";
  id: string;
  palette: Uint8ClampedArray;
  size: number;
  tileUrl?: string;
};

type WorkerRequest = ImageRequest | GradientRequest;

type WorkerResponse = {
  id: string;
  bitmap?: ImageBitmap;
  error?: string;
};

const workerScope = self as DedicatedWorkerGlobalScope;

workerScope.onmessage = (event: MessageEvent<WorkerRequest>) => {
  const payload = event.data;
  if (!payload) return;
  if (payload.type === "image") {
    handleImage(payload).catch((error) => {
      postError(payload.id, error);
    });
    return;
  }
  if (payload.type === "gradient") {
    handleGradient(payload).catch((error) => {
      postError(payload.id, error);
    });
  }
};

function postError(id: string, error: unknown) {
  const message = error instanceof Error ? error.message : "Unknown worker error";
  const response: WorkerResponse = { id, error: message };
  workerScope.postMessage(response);
}

async function handleImage({ id, src, size }: ImageRequest) {
  const response = await fetch(src, { cache: "force-cache" });
  if (!response.ok) {
    throw new Error(`Failed to fetch image (${response.status})`);
  }
  const blob = await response.blob();
  const bitmap = await createCoverBitmap(blob, size);
  const result: WorkerResponse = { id, bitmap };
  workerScope.postMessage(result, [bitmap]);
}

async function createCoverBitmap(blob: Blob, size: number): Promise<ImageBitmap> {
  const source = await createImageBitmap(blob);
  if (typeof OffscreenCanvas === "undefined") {
    const resized = await createImageBitmap(blob, {
      resizeWidth: size,
      resizeHeight: size,
      resizeQuality: "high",
    });
    source.close();
    return resized;
  }
  const canvas = new OffscreenCanvas(size, size);
  const ctx = canvas.getContext("2d");
  if (!ctx) {
    const resized = await createImageBitmap(blob, {
      resizeWidth: size,
      resizeHeight: size,
      resizeQuality: "high",
    });
    source.close();
    return resized;
  }
  const scale = Math.max(size / source.width, size / source.height);
  const drawWidth = Math.round(source.width * scale);
  const drawHeight = Math.round(source.height * scale);
  const dx = Math.round((size - drawWidth) / 2);
  const dy = Math.round((size - drawHeight) / 2);
  ctx.clearRect(0, 0, size, size);
  ctx.drawImage(source, dx, dy, drawWidth, drawHeight);
  source.close();
  return canvas.transferToImageBitmap();
}

async function handleGradient({ id, palette, size, tileUrl }: GradientRequest) {
  const bitmap = tileUrl
    ? await renderTerrainPreview(tileUrl, palette, size)
    : await renderGradientPreview(palette, size);
  const result: WorkerResponse = { id, bitmap };
  workerScope.postMessage(result, [bitmap]);
}

async function renderGradientPreview(palette: Uint8ClampedArray, size: number): Promise<ImageBitmap> {
  const imageData = new ImageData(size, size);
  const dest = imageData.data;
  for (let y = 0; y < size; y += 1) {
    for (let x = 0; x < size; x += 1) {
      const t = size <= 1 ? 0 : x / (size - 1);
      const paletteIndex = Math.min(255, Math.max(0, Math.round(t * 255)));
      const srcOffset = paletteIndex * 4;
      const destOffset = (y * size + x) * 4;
      dest[destOffset] = palette[srcOffset];
      dest[destOffset + 1] = palette[srcOffset + 1];
      dest[destOffset + 2] = palette[srcOffset + 2];
      dest[destOffset + 3] = 255;
    }
  }
  return await createImageBitmap(imageData);
}

type ParsedTiff = {
  data: Float32Array;
  width: number;
  height: number;
  min: number;
  max: number;
};

const TYPE_SIZES: Record<number, number> = {
  1: 1, // BYTE
  2: 1, // ASCII
  3: 2, // SHORT
  4: 4, // LONG
  5: 8, // RATIONAL
  12: 8, // DOUBLE
};

function readUInt16(view: DataView, offset: number, little: boolean): number {
  return view.getUint16(offset, little);
}

function readUInt32(view: DataView, offset: number, little: boolean): number {
  return view.getUint32(offset, little);
}

function readValues(
  view: DataView,
  type: number,
  count: number,
  valueOffset: number,
  little: boolean,
): number[] {
  const size = TYPE_SIZES[type];
  if (!size) throw new Error(`Unsupported TIFF field type ${type}`);
  const totalSize = size * count;
  const offset = totalSize <= 4 ? valueOffset : readUInt32(view, valueOffset, little);
  const values: number[] = [];
  for (let i = 0; i < count; i += 1) {
    const entryOffset = offset + i * size;
    switch (type) {
      case 3:
        values.push(readUInt16(view, entryOffset, little));
        break;
      case 4:
        values.push(readUInt32(view, entryOffset, little));
        break;
      case 5: {
        const numerator = readUInt32(view, entryOffset, little);
        const denominator = readUInt32(view, entryOffset + 4, little);
        values.push(denominator !== 0 ? numerator / denominator : 0);
        break;
      }
      case 12: {
        values.push(view.getFloat64(entryOffset, little));
        break;
      }
      default:
        values.push(view.getUint8(entryOffset));
    }
  }
  return values;
}

async function decompressDeflate(data: ArrayBuffer): Promise<ArrayBuffer> {
  const ctor = (globalThis as unknown as { DecompressionStream?: typeof DecompressionStream }).DecompressionStream;
  if (typeof ctor === "function") {
    const ds = new ctor("deflate");
    const stream = new Response(data).body?.pipeThrough(ds);
    if (!stream) throw new Error("Failed to create deflate stream");
    return await new Response(stream).arrayBuffer();
  }
  throw new Error("Deflate decompression unsupported in this environment");
}

async function parseGeoTiff(buffer: ArrayBuffer): Promise<ParsedTiff> {
  const view = new DataView(buffer);
  const byteOrder = view.getUint16(0, false);
  const little = byteOrder === 0x4949;
  const magic = readUInt16(view, 2, little);
  if (magic !== 42) throw new Error("Unsupported TIFF magic number");

  let ifdOffset = readUInt32(view, 4, little);
  if (ifdOffset === 0) throw new Error("TIFF has no IFD");

  const directory: Record<number, number[]> = {};
  const visited = new Set<number>();

  while (ifdOffset && !visited.has(ifdOffset)) {
    visited.add(ifdOffset);
    const numEntries = readUInt16(view, ifdOffset, little);
    let entryOffset = ifdOffset + 2;
    for (let entryIndex = 0; entryIndex < numEntries; entryIndex += 1) {
      const tag = readUInt16(view, entryOffset, little);
      const type = readUInt16(view, entryOffset + 2, little);
      const count = readUInt32(view, entryOffset + 4, little);
      const valueOffset = entryOffset + 8;
      directory[tag] = readValues(view, type, count, valueOffset, little);
      entryOffset += 12;
    }
    ifdOffset = readUInt32(view, entryOffset, little);
  }

  const width = directory[256]?.[0];
  const height = directory[257]?.[0];
  const bitsPerSample = directory[258]?.[0] ?? 32;
  const compression = directory[259]?.[0] ?? 1;
  const rowsPerStrip = directory[278]?.[0] ?? height;
  const stripOffsets = directory[273] ?? [];
  const stripByteCounts = directory[279] ?? [];
  const sampleFormat = directory[339]?.[0] ?? 1;

  if (!width || !height || stripOffsets.length === 0 || stripByteCounts.length === 0) {
    throw new Error("Incomplete GeoTIFF metadata");
  }
  if (bitsPerSample !== 32 || sampleFormat !== 3) {
    throw new Error(`Unsupported GeoTIFF sample format (bitsPerSample=${bitsPerSample}, sampleFormat=${sampleFormat})`);
  }
  if (compression !== 1 && compression !== 8) {
    throw new Error(`Unsupported GeoTIFF compression (${compression})`);
  }

  const floatData = new Float32Array(width * height);
  let outOffset = 0;
  let remainingRows = height;

  for (let i = 0; i < stripOffsets.length; i += 1) {
    const stripOffset = stripOffsets[i];
    const byteCount = stripByteCounts[i];
    const rows = Math.min(rowsPerStrip, remainingRows);
    const expectedBytes = rows * width * 4;
    const stripSlice = buffer.slice(stripOffset, stripOffset + byteCount);

    let stripBuffer: ArrayBuffer;
    if (compression === 8) {
      stripBuffer = await decompressDeflate(stripSlice);
    } else {
      stripBuffer = stripSlice;
    }

    if (stripBuffer.byteLength < expectedBytes) {
      throw new Error("Strip byte count smaller than expected");
    }

    const rowView = new DataView(stripBuffer);
    for (let row = 0; row < rows; row += 1) {
      for (let col = 0; col < width; col += 1) {
        const sampleOffset = (row * width + col) * 4;
        floatData[outOffset + row * width + col] = rowView.getFloat32(sampleOffset, little);
      }
    }
    outOffset += rows * width;
    remainingRows -= rows;
  }

  let min = Number.POSITIVE_INFINITY;
  let max = Number.NEGATIVE_INFINITY;
  for (let i = 0; i < floatData.length; i += 1) {
    const value = floatData[i];
    if (!Number.isFinite(value)) continue;
    if (value < min) min = value;
    if (value > max) max = value;
  }
  if (!Number.isFinite(min) || !Number.isFinite(max)) {
    min = 0;
    max = 1;
  }

  return { data: floatData, width, height, min, max };
}

async function renderTerrainPreview(tileUrl: string, palette: Uint8ClampedArray, size: number): Promise<ImageBitmap> {
  const normalizedUrl = tileUrl.toLowerCase();
  if (normalizedUrl.endsWith(".png")) {
    const tiffUrl = tileUrl.replace(/\.png$/i, ".tif");
    const tiff = await fetch(tiffUrl, { cache: "force-cache" }).catch(() => null);
    if (tiff && tiff.ok) {
      const buffer = await tiff.arrayBuffer();
      const parsed = await parseGeoTiff(buffer);
      return await renderTerrainFromHeightData(parsed, palette, size);
    }
  }

  const response = await fetch(tileUrl, { cache: "force-cache" });
  if (!response.ok) {
    throw new Error(`Failed to fetch terrain tile (${response.status})`);
  }
  if (typeof OffscreenCanvas === "undefined") {
    return await renderGradientPreview(palette, size);
  }
  const blob = await response.blob();
  const bitmap = await createImageBitmap(blob);
  const canvas = new OffscreenCanvas(size, size);
  const ctx = canvas.getContext("2d");
  if (!ctx) return await renderGradientPreview(palette, size);
  ctx.drawImage(bitmap, 0, 0, size, size);
  bitmap.close();
  const imageData = ctx.getImageData(0, 0, size, size);
  const data = imageData.data;
  for (let i = 0; i < data.length; i += 4) {
    const r = data[i];
    const g = data[i + 1];
    const b = data[i + 2];
    const gray = Math.round(0.2126 * r + 0.7152 * g + 0.0722 * b);
    const paletteOffset = gray * 4;
    data[i] = palette[paletteOffset];
    data[i + 1] = palette[paletteOffset + 1];
    data[i + 2] = palette[paletteOffset + 2];
    data[i + 3] = 255;
  }
  ctx.putImageData(imageData, 0, 0);
  return canvas.transferToImageBitmap();
}

async function renderTerrainFromHeightData(parsed: ParsedTiff, palette: Uint8ClampedArray, size: number): Promise<ImageBitmap> {
  const { data, width, height, min, max } = parsed;
  const imageData = new ImageData(size, size);
  const dest = imageData.data;
  const range = Math.max(1e-6, max - min);
  for (let y = 0; y < size; y += 1) {
    const srcY = height <= 1 ? 0 : Math.round((y / (size - 1)) * (height - 1));
    for (let x = 0; x < size; x += 1) {
      const srcX = width <= 1 ? 0 : Math.round((x / (size - 1)) * (width - 1));
      const heightValue = data[srcY * width + srcX];
      const normalized = Math.min(1, Math.max(0, (heightValue - min) / range));
      const paletteIndex = Math.min(255, Math.max(0, Math.round(normalized * 255)));
      const paletteOffset = paletteIndex * 4;
      const destOffset = (y * size + x) * 4;
      dest[destOffset] = palette[paletteOffset];
      dest[destOffset + 1] = palette[paletteOffset + 1];
      dest[destOffset + 2] = palette[paletteOffset + 2];
      dest[destOffset + 3] = 255;
    }
  }
  return await createImageBitmap(imageData);
}
